script:
$env:Path += ";C:\Users\E\AppData\Local\hermes\bin"
"=== current model config ==="
hermes config get model.default 2>&1 | Select-Object -First 2
"=== testing with default ==="
$job = Start-Job -ScriptBlock {
  $env:Path += ";C:\Users\E\AppData\Local\hermes\bin"
  hermes -z "Say HI" 2>&1
}
if (Wait-Job $job -Timeout 60) {
  $out = Receive-Job $job
